-- ===========================================
-- Louisiana LDWF aerial survey history 2004-2018 (2026-11-19)
--
-- LDWF's statewide coastal reports from Sept 2004 to Dec 2018, read from each PDF's Table 1 by
-- position (no LLM), the same reader as fix-ldwf-history-2026-11-18.sql. Loaded: 48 reports
-- whose species add up exactly to the table's TOTAL DUCKS row. Left out: the "Coastal WMAs and
-- Refuges" reports (a smaller area, not the statewide survey), the 1977-2003 summary, and 8
-- reports whose species can't match their own totals: off by LDWF's rounding (Dec 2005, Jan 2007,
-- Jan 2012, Jan 2016) or LDWF typos (Jan 2013, Nov 2010, Nov 2012, Nov 2018).
-- Dates are the report date, except three January surveys reported in February (2014, 2015,
-- 2018), stored under their last coastal-zone flight day so they stay January surveys.
-- Adds only: nothing for this location is stored before 2019. Every survey must add up to its
-- TOTAL DUCKS after, or nothing is changed. Owner approval required before running on production.
-- ===========================================
\set ON_ERROR_STOP on
BEGIN;

CREATE TEMP TABLE ins (survey_date date, url text, slug text, count int, total int) ON COMMIT DROP;

DO $$
DECLARE loc uuid; r record; n int;
BEGIN
  SELECT id INTO STRICT loc FROM locations WHERE name = 'Louisiana - LDWF Aerial Survey';
  SELECT count(*) INTO n FROM refuge_counts WHERE location_id = loc AND survey_date < '2019-01-01';
  IF n <> 0 THEN RAISE EXCEPTION 'LDWF already has % rows before 2019', n; END IF;

  SELECT loc, sp.id, i.survey_date, i.count, 'aerial_monthly', i.url,
         jsonb_build_object('checked', '2026-11-19', 'read', 'LDWF Table 1, species add up to TOTAL DUCKS')
  FROM ins i JOIN species sp ON sp.slug = i.slug;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> (SELECT count(*) FROM ins) THEN RAISE EXCEPTION 'inserted % of % rows (unknown species slug?)', n, (SELECT count(*) FROM ins); END IF;

  FOR r IN SELECT survey_date, max(total) AS total FROM ins GROUP BY 1 LOOP
    SELECT sum(count) INTO n FROM refuge_counts WHERE location_id = loc AND survey_date::date = r.survey_date;
    IF n <> r.total THEN RAISE EXCEPTION '%: stored % but TOTAL DUCKS is %', r.survey_date, n, r.total; END IF;
  END LOOP;
END $$;

COMMIT;

SELECT extract(year FROM survey_date)::int AS year, count(DISTINCT survey_date) AS surveys, count(*) AS rows
FROM refuge_counts rc JOIN locations l ON l.id = rc.location_id
WHERE l.name = 'Louisiana - LDWF Aerial Survey' GROUP BY 1 ORDER BY 1;
